import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

export const experimental_ppr = true

async function CardStatsWrapper() {
  const res = await fetch('https://api.example.com/dashboard/stats', {
    next: { revalidate: 60 },
  })
  const data = await res.json()
  return (
    <CardStats totalRevenue={data.totalRevenue} totalInvoices={data.totalInvoices} />
  )
}

async function RevenueChartWrapper() {
  const res = await fetch('https://api.example.com/dashboard/revenue', {
    next: { revalidate: 300 },
  })
  const data = await res.json()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesWrapper() {
  const res = await fetch('https://api.example.com/dashboard/invoices', {
    next: { revalidate: 30 },
  })
  const data = await res.json()
  return <LatestInvoices invoices={data.invoices} />
}

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton">
        <h2>Total Revenue</h2>
        <div className="skeleton-text" />
      </div>
      <div className="card skeleton">
        <h2>Total Invoices</h2>
        <div className="skeleton-text" />
      </div>
    </div>
  )
}

function ChartSkeleton() {
  return (
    <div className="chart skeleton">
      <h2>Revenue</h2>
      <div className="skeleton-bars" />
    </div>
  )
}

function InvoicesSkeleton() {
  return (
    <div className="invoices skeleton">
      <h2>Latest Invoices</h2>
      <div className="skeleton-list" />
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsWrapper />
      </Suspense>
      <Suspense fallback={<ChartSkeleton />}>
        <RevenueChartWrapper />
      </Suspense>
      <Suspense fallback={<InvoicesSkeleton />}>
        <LatestInvoicesWrapper />
      </Suspense>
    </main>
  )
}

